/* Analytics, one pipeline: every page of the creator page, the OnePage and each website is one event with the property it happened on. analytics_events gets the property (property_type creator_page, onepage or website, and property_id: the website's store_theme_installs id or the OnePage's id), the page's path, and a link's id and destination for the new link_click event, which the event type check now allows (NOT VALID: old rows are not rechecked). Four indexes for the reads the reports and the tracker make. Old page views get their property from the address they were recorded on (the path is left empty: for a visitor who accepted analytics the stored address is the visit's first page, not the page itself); a second run changes nothing. A daily rollup per creator, property and UTC day (analytics_property_daily), the days it holds (analytics_rollup_days) and the function that refreshes a day (analytics_refresh_property_day), which the daily cron calls; server only, creators may read their own rows. analytics_visit_tally and analytics_all_time leave OnePage page views out, so the Storelib view counts them once, as before, in the OnePage view. The reading side: the rollup keeps each day's browsers and the quarter hour each visit began (session_slots), so a visit falls in the right day of any time zone; a day rolled up before those columns existed is forgotten and rolled up again. analytics_property_counts counts one or more UTC days from the events by the rules the rollup is made with, and analytics_report answers the Analytics page for one creator, one property (or all of them) and two periods: unique visitors, page views and link clicks per chart bucket from the events, visits and where they came from from the rollup for whole past days and from the events for the rest, and the top pages, products, links and started checkouts. Both are server only. docs/analytics/events.md is the contract and lib/analytics/reports.ts says what each figure counts. Run after 25 and 32. Can take a minute on a large events table. */
ALTER TABLE public.analytics_events ADD COLUMN IF NOT EXISTS visitor_id text, ADD COLUMN IF NOT EXISTS session_id text, ADD COLUMN IF NOT EXISTS referrer text, ADD COLUMN IF NOT EXISTS referrer_domain text, ADD COLUMN IF NOT EXISTS utm_source text, ADD COLUMN IF NOT EXISTS utm_medium text, ADD COLUMN IF NOT EXISTS utm_campaign text, ADD COLUMN IF NOT EXISTS utm_term text, ADD COLUMN IF NOT EXISTS utm_content text, ADD COLUMN IF NOT EXISTS country_code text, ADD COLUMN IF NOT EXISTS country_name text, ADD COLUMN IF NOT EXISTS region text, ADD COLUMN IF NOT EXISTS city text, ADD COLUMN IF NOT EXISTS device_type text, ADD COLUMN IF NOT EXISTS browser text, ADD COLUMN IF NOT EXISTS os text, ADD COLUMN IF NOT EXISTS page_url text, ADD COLUMN IF NOT EXISTS screen_width integer, ADD COLUMN IF NOT EXISTS screen_height integer, ADD COLUMN IF NOT EXISTS language text, ADD COLUMN IF NOT EXISTS source_category text, ADD COLUMN IF NOT EXISTS property_type text, ADD COLUMN IF NOT EXISTS property_id uuid, ADD COLUMN IF NOT EXISTS path text, ADD COLUMN IF NOT EXISTS link_id text, ADD COLUMN IF NOT EXISTS link_url text;
ALTER TABLE public.analytics_events DROP CONSTRAINT IF EXISTS analytics_events_event_type_check;
ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_event_type_check CHECK (event_type IN ('view', 'purchase', 'session_start', 'store_view', 'product_view', 'add_to_cart', 'checkout_start', 'buy_click', 'checkout_complete', 'download', 'link_click')) NOT VALID;
ALTER TABLE public.analytics_events DROP CONSTRAINT IF EXISTS analytics_events_property_type_check;
ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_property_type_check CHECK (property_type IS NULL OR property_type IN ('creator_page', 'onepage', 'website')) NOT VALID;
ALTER TABLE public.analytics_events DROP CONSTRAINT IF EXISTS analytics_events_path_check;
ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_path_check CHECK (path IS NULL OR (char_length(path) <= 300 AND left(path, 1) = '/')) NOT VALID;
CREATE INDEX IF NOT EXISTS idx_analytics_events_property_type_time ON public.analytics_events (creator_id, property_type, property_id, event_type, created_at);
CREATE INDEX IF NOT EXISTS idx_analytics_events_property_path_time ON public.analytics_events (creator_id, property_type, property_id, path, created_at) WHERE event_type = 'view' AND path IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_analytics_events_visitor_time ON public.analytics_events (visitor_id, created_at) WHERE visitor_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_analytics_events_time_brin ON public.analytics_events USING brin (created_at);
DO $$ DECLARE has_purpose boolean; creator_hosts text := $h$ ('storelib.com', 'www.storelib.com', 'localhost', '127.0.0.1') $h$; v_rows bigint; BEGIN has_purpose := EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'custom_domains' AND column_name = 'purpose'); EXECUTE format($q$ WITH sole AS (SELECT creator_id, (array_agg(id))[1] AS install_id FROM public.store_theme_installs GROUP BY creator_id HAVING count(*) = 1), placed AS ( SELECT e.id, e.creator_id, %1$s AS host FROM public.analytics_events e WHERE e.property_type IS NULL AND e.event_type = 'view' AND e.page_url ~* '^https?://[^/?#]+' ), typed AS ( SELECT p.id, p.creator_id, CASE WHEN p.host IN %2$s OR p.host LIKE '%%.vercel.app' THEN 'creator_page' WHEN %3$s THEN 'creator_page' ELSE 'website' END AS property_type FROM placed p WHERE p.host IS NOT NULL ) UPDATE public.analytics_events e SET property_type = t.property_type, property_id = CASE WHEN t.property_type = 'website' THEN (SELECT s.install_id FROM sole s WHERE s.creator_id = t.creator_id) END FROM typed t WHERE e.id = t.id AND e.property_type IS NULL $q$, 'lower(substring(e.page_url from ''^[a-zA-Z][a-zA-Z0-9+.-]*://([^/?#:]+)''))', creator_hosts, CASE WHEN has_purpose THEN $c$EXISTS (SELECT 1 FROM public.custom_domains d WHERE d.creator_id = p.creator_id AND d.domain = regexp_replace(p.host, '^www\.', '') AND d.purpose = 'creator_page')$c$ ELSE 'false' END); GET DIAGNOSTICS v_rows = ROW_COUNT; RAISE NOTICE 'analytics_events: % old page views placed on a property', v_rows; END $$;
CREATE TABLE IF NOT EXISTS public.analytics_property_daily ( creator_id uuid NOT NULL, property_type text NOT NULL, property_id uuid, day date NOT NULL, visitors integer NOT NULL DEFAULT 0, sessions integer NOT NULL DEFAULT 0, bounces integer NOT NULL DEFAULT 0, page_views integer NOT NULL DEFAULT 0, product_views integer NOT NULL DEFAULT 0, link_clicks integer NOT NULL DEFAULT 0, buy_clicks integer NOT NULL DEFAULT 0, checkout_starts integer NOT NULL DEFAULT 0, sources jsonb NOT NULL DEFAULT '{}'::jsonb, referrers jsonb NOT NULL DEFAULT '{}'::jsonb, campaigns jsonb NOT NULL DEFAULT '{}'::jsonb, devices jsonb NOT NULL DEFAULT '{}'::jsonb, countries jsonb NOT NULL DEFAULT '{}'::jsonb, browsers jsonb NOT NULL DEFAULT '{}'::jsonb, paths jsonb NOT NULL DEFAULT '{}'::jsonb, landing_paths jsonb NOT NULL DEFAULT '{}'::jsonb, session_slots jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT analytics_property_daily_type_check CHECK (property_type IN ('creator_page', 'onepage', 'website')) );
ALTER TABLE public.analytics_property_daily ADD COLUMN IF NOT EXISTS browsers jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS session_slots jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE UNIQUE INDEX IF NOT EXISTS analytics_property_daily_key ON public.analytics_property_daily (creator_id, property_type, (coalesce(property_id, '00000000-0000-0000-0000-000000000000'::uuid)), day);
CREATE INDEX IF NOT EXISTS analytics_property_daily_day ON public.analytics_property_daily (day);
ALTER TABLE public.analytics_property_daily ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "creators read own property days" ON public.analytics_property_daily;
CREATE POLICY "creators read own property days" ON public.analytics_property_daily FOR SELECT USING (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = (SELECT auth.uid())));
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.analytics_property_daily FROM anon, authenticated;
DROP POLICY IF EXISTS "Allow insert analytics" ON public.analytics_events;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.analytics_events FROM anon, authenticated;
CREATE TABLE IF NOT EXISTS public.analytics_rollup_days (day date PRIMARY KEY, refreshed_at timestamptz NOT NULL DEFAULT now(), properties integer NOT NULL DEFAULT 0);
DO $$ BEGIN /* A day rolled up before session_slots existed is forgotten (only the note that it is rolled up, not a row of anybody's), so the reports count it from the events until the daily cron rolls it up again. */ DELETE FROM public.analytics_rollup_days r WHERE EXISTS (SELECT 1 FROM public.analytics_property_daily d WHERE d.day = r.day AND d.sessions > 0 AND d.session_slots = '{}'::jsonb); END $$;
ALTER TABLE public.analytics_rollup_days ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.analytics_rollup_days FROM anon, authenticated;
CREATE OR REPLACE FUNCTION public.analytics_property_counts(p_from timestamptz, p_to timestamptz, p_creator_id uuid DEFAULT NULL, p_property_type text DEFAULT NULL, p_property_id uuid DEFAULT NULL, p_default_website uuid DEFAULT NULL, p_product_id uuid DEFAULT NULL) RETURNS TABLE (creator_id uuid, property_type text, property_id uuid, day date, visitors integer, sessions integer, bounces integer, page_views integer, product_views integer, link_clicks integer, buy_clicks integer, checkout_starts integer, sources jsonb, referrers jsonb, campaigns jsonb, devices jsonb, countries jsonb, browsers jsonb, paths jsonb, landing_paths jsonb, session_slots jsonb) LANGUAGE plpgsql STABLE SET search_path = public AS $fn$ DECLARE v_first date; v_last date; v_where text := ''; BEGIN IF p_from IS NULL OR p_to IS NULL OR p_to <= p_from THEN RETURN; END IF; v_first := (p_from AT TIME ZONE 'UTC')::date; v_last := ((p_to - interval '1 microsecond') AT TIME ZONE 'UTC')::date; /* Only the conditions asked for, so each call is planned for its own arguments and reads one creator's rows by their index. */ IF p_creator_id IS NOT NULL THEN v_where := v_where || ' AND e.creator_id = $3'; END IF; IF p_property_type IS NOT NULL THEN v_where := v_where || ' AND e.property_type = $4'; IF p_property_type = 'website' AND p_property_id IS NOT NULL THEN v_where := v_where || CASE WHEN p_property_id = p_default_website THEN ' AND (e.property_id = $5 OR e.property_id IS NULL)' ELSE ' AND e.property_id = $5' END; END IF; END IF; IF p_product_id IS NOT NULL THEN v_where := v_where || ' AND e.product_id = $6'; END IF; RETURN QUERY EXECUTE format($q$ WITH ev AS (SELECT e.id, e.creator_id, e.property_type, e.property_id, e.event_type, e.product_id, e.created_at, (e.created_at AT TIME ZONE 'UTC')::date AS d, coalesce(e.path, '(unknown)') AS path, coalesce(nullif(e.source_category, ''), 'direct') AS source, coalesce(nullif(lower(regexp_replace(coalesce(e.referrer_domain, ''), '^www\.', '')), ''), 'direct') AS referrer, nullif(e.utm_campaign, '') AS campaign, coalesce(nullif(lower(e.device_type), ''), 'unknown') AS device, coalesce(nullif(upper(e.country_code), ''), 'unknown') AS country, coalesce(nullif(lower(e.browser), ''), 'unknown') AS browser, e.property_type || ':' || coalesce(e.property_id::text, '') AS pk, coalesce(nullif(e.visitor_id::text, ''), nullif(e.session_id::text, ''), 'e:' || e.id::text) AS vkey, CASE WHEN coalesce(e.session_id::text, '') <> '' THEN 's:' || e.session_id::text WHEN coalesce(e.visitor_id::text, '') <> '' THEN 'v:' || e.visitor_id::text || ':' || to_char(e.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD') ELSE 'e:' || e.id::text END AS skey FROM public.analytics_events e WHERE e.created_at >= $7 AND e.created_at < $2 AND e.property_type IS NOT NULL AND e.event_type IN ('view', 'link_click', 'buy_click', 'checkout_start') %s), today AS (SELECT * FROM ev WHERE created_at >= $1), looked AS (SELECT v.*, v.d AS for_day FROM ev v WHERE v.event_type = 'view' AND v.d >= $8 UNION ALL SELECT v.*, v.d + 1 AS for_day FROM ev v WHERE v.event_type = 'view' AND v.d + 1 >= $8 AND v.d + 1 <= $9), firsts AS (SELECT DISTINCT ON (creator_id, pk, skey, for_day) creator_id, pk, skey, for_day, created_at, path, source, referrer, campaign, device, country, browser FROM looked ORDER BY creator_id, pk, skey, for_day, created_at, id), pages AS (SELECT creator_id, pk, skey, for_day, count(*) AS n FROM looked GROUP BY 1, 2, 3, 4), starts AS (SELECT f.creator_id, f.pk, f.for_day AS day, f.path, f.source, f.referrer, f.campaign, f.device, f.country, f.browser, p.n AS pages, (floor(extract(epoch FROM f.created_at - (f.for_day::timestamp AT TIME ZONE 'UTC')) / 900))::int::text AS slot FROM firsts f JOIN pages p USING (creator_id, pk, skey, for_day) WHERE f.created_at >= $1 AND (f.created_at AT TIME ZONE 'UTC')::date = f.for_day), keys AS (SELECT DISTINCT creator_id, pk, property_type, property_id, d AS day FROM today), counts AS (SELECT creator_id, pk, d AS day, count(*) FILTER (WHERE event_type = 'view') AS page_views, count(*) FILTER (WHERE event_type = 'view' AND product_id IS NOT NULL) AS product_views, count(DISTINCT vkey) FILTER (WHERE event_type = 'view') AS visitors, count(*) FILTER (WHERE event_type = 'link_click') AS link_clicks, count(DISTINCT skey) FILTER (WHERE event_type = 'buy_click') AS buy_clicks, count(DISTINCT skey) FILTER (WHERE event_type = 'checkout_start') AS checkout_starts FROM today GROUP BY 1, 2, 3), sess AS (SELECT creator_id, pk, day, count(*) AS sessions, count(*) FILTER (WHERE pages = 1) AS bounces FROM starts GROUP BY 1, 2, 3), dims AS (SELECT creator_id, pk, day, 'source' AS kind, source AS k, count(*) AS n FROM starts GROUP BY 1, 2, 3, 5 UNION ALL SELECT creator_id, pk, day, 'referrer', referrer, count(*) FROM starts GROUP BY 1, 2, 3, 5 UNION ALL SELECT creator_id, pk, day, 'campaign', campaign, count(*) FROM starts WHERE campaign IS NOT NULL GROUP BY 1, 2, 3, 5 UNION ALL SELECT creator_id, pk, day, 'device', device, count(*) FROM starts GROUP BY 1, 2, 3, 5 UNION ALL SELECT creator_id, pk, day, 'country', country, count(*) FROM starts GROUP BY 1, 2, 3, 5 UNION ALL SELECT creator_id, pk, day, 'browser', browser, count(*) FROM starts GROUP BY 1, 2, 3, 5 UNION ALL SELECT creator_id, pk, day, 'landing', path, count(*) FROM starts GROUP BY 1, 2, 3, 5 UNION ALL SELECT creator_id, pk, day, 'slot', slot, count(*) FROM starts GROUP BY 1, 2, 3, 5 UNION ALL SELECT creator_id, pk, d, 'path', path, count(*) FROM today WHERE event_type = 'view' GROUP BY 1, 2, 3, 5), ranked AS (SELECT creator_id, pk, day, kind, k, n, row_number() OVER (PARTITION BY creator_id, pk, day, kind ORDER BY n DESC, k) AS rn FROM dims), capped AS (SELECT creator_id, pk, day, kind, CASE WHEN rn <= CASE kind WHEN 'country' THEN 300 WHEN 'path' THEN 200 WHEN 'landing' THEN 200 WHEN 'slot' THEN 96 ELSE 100 END THEN k ELSE '(other)' END AS k, sum(n) AS n FROM ranked GROUP BY 1, 2, 3, 4, 5), maps AS (SELECT creator_id, pk, day, jsonb_object_agg(kind, m) AS m FROM (SELECT creator_id, pk, day, kind, jsonb_object_agg(k, n) AS m FROM capped GROUP BY 1, 2, 3, 4) x GROUP BY 1, 2, 3) SELECT k.creator_id, k.property_type, k.property_id, k.day, coalesce(c.visitors, 0)::int, coalesce(s.sessions, 0)::int, coalesce(s.bounces, 0)::int, coalesce(c.page_views, 0)::int, coalesce(c.product_views, 0)::int, coalesce(c.link_clicks, 0)::int, coalesce(c.buy_clicks, 0)::int, coalesce(c.checkout_starts, 0)::int, coalesce(m.m -> 'source', '{}'::jsonb), coalesce(m.m -> 'referrer', '{}'::jsonb), coalesce(m.m -> 'campaign', '{}'::jsonb), coalesce(m.m -> 'device', '{}'::jsonb), coalesce(m.m -> 'country', '{}'::jsonb), coalesce(m.m -> 'browser', '{}'::jsonb), coalesce(m.m -> 'path', '{}'::jsonb), coalesce(m.m -> 'landing', '{}'::jsonb), coalesce(m.m -> 'slot', '{}'::jsonb) FROM keys k LEFT JOIN counts c ON c.creator_id = k.creator_id AND c.pk = k.pk AND c.day = k.day LEFT JOIN sess s ON s.creator_id = k.creator_id AND s.pk = k.pk AND s.day = k.day LEFT JOIN maps m ON m.creator_id = k.creator_id AND m.pk = k.pk AND m.day = k.day $q$, v_where) USING p_from, p_to, p_creator_id, p_property_type, p_property_id, p_product_id, (v_first - 1)::timestamp AT TIME ZONE 'UTC', v_first, v_last; END; $fn$;
REVOKE ALL ON FUNCTION public.analytics_property_counts(timestamptz, timestamptz, uuid, text, uuid, uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_property_counts(timestamptz, timestamptz, uuid, text, uuid, uuid, uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.analytics_refresh_property_day(p_day date, p_creator_id uuid DEFAULT NULL) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ DECLARE v_rows integer; BEGIN IF p_day IS NULL THEN RAISE EXCEPTION 'analytics_refresh_property_day: a day is needed'; END IF; PERFORM pg_advisory_xact_lock(hashtext('analytics_property_daily:' || p_day::text)); DELETE FROM public.analytics_property_daily WHERE day = p_day AND (p_creator_id IS NULL OR creator_id = p_creator_id); INSERT INTO public.analytics_property_daily (creator_id, property_type, property_id, day, visitors, sessions, bounces, page_views, product_views, link_clicks, buy_clicks, checkout_starts, sources, referrers, campaigns, devices, countries, browsers, paths, landing_paths, session_slots, updated_at) SELECT c.creator_id, c.property_type, c.property_id, c.day, c.visitors, c.sessions, c.bounces, c.page_views, c.product_views, c.link_clicks, c.buy_clicks, c.checkout_starts, c.sources, c.referrers, c.campaigns, c.devices, c.countries, c.browsers, c.paths, c.landing_paths, c.session_slots, now() FROM public.analytics_property_counts(p_day::timestamp AT TIME ZONE 'UTC', (p_day + 1)::timestamp AT TIME ZONE 'UTC', p_creator_id) c; GET DIAGNOSTICS v_rows = ROW_COUNT; IF p_creator_id IS NULL THEN INSERT INTO public.analytics_rollup_days (day, refreshed_at, properties) VALUES (p_day, now(), v_rows) ON CONFLICT (day) DO UPDATE SET refreshed_at = excluded.refreshed_at, properties = excluded.properties; END IF; RETURN v_rows; END; $fn$;
REVOKE ALL ON FUNCTION public.analytics_refresh_property_day(date, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_refresh_property_day(date, uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.analytics_visit_tally( p_creator_id uuid, p_product_id uuid, p_time_zone text, p_cur_start bigint, p_cur_end bigint, p_prev_start bigint, p_prev_end bigint, p_cur_starts bigint[], p_prev_starts bigint[], p_detail boolean DEFAULT true ) RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS $fn$WITH bounds AS ( SELECT timestamptz 'epoch' + p_cur_start * interval '1 millisecond' AS cs, timestamptz 'epoch' + p_cur_end * interval '1 millisecond' AS ce, timestamptz 'epoch' + p_prev_start * interval '1 millisecond' AS ps, timestamptz 'epoch' + p_prev_end * interval '1 millisecond' AS pe, coalesce(cardinality(p_cur_starts), 0) AS n ), win AS ( SELECT 'cur'::text AS w, b.cs AS ws, b.ce AS we, ARRAY(SELECT timestamptz 'epoch' + x * interval '1 millisecond' FROM unnest(coalesce(p_cur_starts, '{}'::bigint[])) WITH ORDINALITY u(x, i) ORDER BY i) AS starts FROM bounds b UNION ALL SELECT 'prev'::text, b.ps, b.pe, ARRAY(SELECT timestamptz 'epoch' + x * interval '1 millisecond' FROM unnest(coalesce(p_prev_starts, '{}'::bigint[])) WITH ORDINALITY u(x, i) ORDER BY i) FROM bounds b ), raw AS ( SELECT e.id, e.created_at, e.session_id::text AS session_id, e.visitor_id::text AS visitor_id, e.source_category, e.referrer_domain, e.utm_campaign, e.country_code, e.country_name, e.city, e.device_type, e.browser, e.os, e.page_url FROM public.analytics_events e, bounds b WHERE e.creator_id = p_creator_id AND e.event_type = 'view' AND (p_product_id IS NULL OR e.product_id = p_product_id) AND e.property_type IS DISTINCT FROM 'onepage' AND e.created_at >= b.cs AND e.created_at < b.ce UNION ALL SELECT e.id, e.created_at, e.session_id::text, e.visitor_id::text, e.source_category, e.referrer_domain, e.utm_campaign, e.country_code, e.country_name, e.city, e.device_type, e.browser, e.os, e.page_url FROM public.analytics_events e, bounds b WHERE e.creator_id = p_creator_id AND e.event_type = 'view' AND (p_product_id IS NULL OR e.product_id = p_product_id) AND e.property_type IS DISTINCT FROM 'onepage' AND e.created_at >= b.ps AND e.created_at < b.pe AND NOT (e.created_at >= b.cs AND e.created_at < b.ce) ), wrows AS ( SELECT w.w, r.id, r.created_at, CASE WHEN cardinality(w.starts) > 0 THEN width_bucket(r.created_at, w.starts) - 1 END AS bucket, (CASE WHEN coalesce(r.session_id, '') <> '' THEN 's:' || r.session_id WHEN coalesce(r.visitor_id, '') <> '' THEN 'v:' || r.visitor_id || ':' || ( floor(extract(epoch FROM r.created_at))::bigint - floor(extract(epoch FROM (r.created_at AT TIME ZONE p_time_zone)::time))::bigint )::text ELSE 'e:' || r.id::text END) COLLATE "C" AS skey FROM raw r JOIN win w ON r.created_at >= w.ws AND r.created_at < w.we ), firsts AS ( SELECT DISTINCT ON (w, skey) w, skey, created_at, id, bucket FROM wrows ORDER BY w, skey, created_at, id ), ranked AS ( SELECT f.w, row_number() OVER (PARTITION BY f.w ORDER BY f.created_at, f.id) AS rank, r.source_category, r.referrer_domain, r.utm_campaign, r.country_code, r.country_name, r.city, r.device_type, r.browser, r.os, split_part(split_part(r.page_url, '#', 1), '?', 1) AS page_url FROM firsts f JOIN raw r ON r.id = f.id WHERE p_detail ), view_b AS (SELECT w, bucket, count(*) AS c FROM wrows GROUP BY w, bucket), session_b AS (SELECT w, bucket, count(*) AS c FROM firsts GROUP BY w, bucket), buckets AS ( SELECT w.w, coalesce((SELECT sum(v.c) FROM view_b v WHERE v.w = w.w), 0) AS views, coalesce((SELECT sum(s.c) FROM session_b s WHERE s.w = w.w), 0) AS sessions, coalesce((SELECT jsonb_agg(coalesce(v.c, 0) ORDER BY g.i) FROM bounds b, generate_series(0, b.n - 1) g(i) LEFT JOIN view_b v ON v.w = w.w AND v.bucket = g.i), '[]'::jsonb) AS view_buckets, coalesce((SELECT jsonb_agg(coalesce(s.c, 0) ORDER BY g.i) FROM bounds b, generate_series(0, b.n - 1) g(i) LEFT JOIN session_b s ON s.w = w.w AND s.bucket = g.i), '[]'::jsonb) AS session_buckets FROM win w ), steps AS ( SELECT w.w, s.event_type, count(DISTINCT s.skey) AS c FROM ( SELECT e.event_type, e.created_at, (CASE WHEN coalesce(e.session_id::text, '') <> '' THEN 's:' || e.session_id::text WHEN coalesce(e.visitor_id::text, '') <> '' THEN 'v:' || e.visitor_id::text || ':' || ( floor(extract(epoch FROM e.created_at))::bigint - floor(extract(epoch FROM (e.created_at AT TIME ZONE p_time_zone)::time))::bigint )::text ELSE 'e:' || e.created_at::text END) COLLATE "C" AS skey FROM public.analytics_events e, bounds b WHERE p_detail AND e.creator_id = p_creator_id AND e.event_type IN ('buy_click', 'checkout_start') AND (p_product_id IS NULL OR e.product_id = p_product_id) AND ((e.created_at >= b.cs AND e.created_at < b.ce) OR (e.created_at >= b.ps AND e.created_at < b.pe)) ) s JOIN win w ON s.created_at >= w.ws AND s.created_at < w.we GROUP BY w.w, s.event_type ), grouped AS ( SELECT w, CASE WHEN GROUPING(source_category) = 0 THEN 'source' WHEN GROUPING(referrer_domain) = 0 THEN 'referrer' WHEN GROUPING(utm_campaign) = 0 THEN 'campaign' WHEN GROUPING(city) = 0 THEN 'city' WHEN GROUPING(country_code) = 0 THEN 'country' WHEN GROUPING(device_type) = 0 THEN 'device' WHEN GROUPING(browser) = 0 THEN 'browser' WHEN GROUPING(os) = 0 THEN 'os' ELSE 'page' END AS kind, CASE WHEN GROUPING(source_category) = 0 THEN jsonb_build_array(source_category) WHEN GROUPING(referrer_domain) = 0 THEN jsonb_build_array(referrer_domain) WHEN GROUPING(utm_campaign) = 0 THEN jsonb_build_array(utm_campaign) WHEN GROUPING(city) = 0 THEN jsonb_build_array(city, country_code, country_name) WHEN GROUPING(country_code) = 0 THEN jsonb_build_array(country_code, country_name) WHEN GROUPING(device_type) = 0 THEN jsonb_build_array(device_type) WHEN GROUPING(browser) = 0 THEN jsonb_build_array(browser) WHEN GROUPING(os) = 0 THEN jsonb_build_array(os) ELSE jsonb_build_array(page_url) END AS cols, count(*) AS n, min(rank) AS r FROM ranked GROUP BY w, GROUPING SETS ((source_category), (referrer_domain), (utm_campaign), (country_code, country_name), (city, country_code, country_name), (device_type), (browser), (os), (page_url)) ), groups AS ( SELECT w, jsonb_object_agg(kind, rows) AS groups FROM (SELECT w, kind, jsonb_agg(cols || jsonb_build_array(n, r) ORDER BY r) AS rows FROM grouped GROUP BY w, kind) k GROUP BY w ), tallies AS ( SELECT w.w, jsonb_build_object( 'views', bk.views, 'view_buckets', bk.view_buckets, 'sessions', bk.sessions, 'session_buckets', bk.session_buckets, 'steps', CASE WHEN p_detail THEN jsonb_build_object( 'buy', coalesce((SELECT s.c FROM steps s WHERE s.w = w.w AND s.event_type = 'buy_click'), 0), 'checkout', coalesce((SELECT s.c FROM steps s WHERE s.w = w.w AND s.event_type = 'checkout_start'), 0) ) END, 'groups', CASE WHEN p_detail THEN coalesce((SELECT g.groups FROM groups g WHERE g.w = w.w), '{}'::jsonb) END ) AS t FROM win w JOIN buckets bk ON bk.w = w.w ) SELECT jsonb_object_agg(w, t) FROM tallies$fn$;
CREATE OR REPLACE FUNCTION public.analytics_all_time(p_creator_id uuid, p_product_id uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS $fn$WITH lines AS ( SELECT coalesce('s:' || nullif(o.stripe_session_id, ''), 'o:' || o.id::text) AS k, o.status, greatest(0, coalesce(o.amount_cents, 0))::bigint AS gross, CASE WHEN o.status = 'refunded' THEN CASE WHEN o.refund_amount_cents > 0 THEN least(o.refund_amount_cents, greatest(0, coalesce(o.amount_cents, 0))) ELSE greatest(0, coalesce(o.amount_cents, 0)) END ELSE 0 END::bigint AS refunded FROM public.orders o WHERE o.creator_id = p_creator_id AND (p_product_id IS NULL OR o.product_id = p_product_id) ), payments AS ( SELECT k, bool_and(coalesce(status = 'failed', false)) AS all_failed, bool_or(coalesce(status = 'pending', false)) AS any_pending, bool_or(coalesce(status = 'disputed', false)) AS any_disputed, greatest(0, sum(gross) - sum(refunded)) AS net FROM lines GROUP BY k ) SELECT jsonb_build_object( 'views', ( SELECT count(*) FROM public.analytics_events e WHERE e.creator_id = p_creator_id AND e.event_type = 'view' AND (p_product_id IS NULL OR e.product_id = p_product_id) AND e.property_type IS DISTINCT FROM 'onepage' ), 'orders', (SELECT count(*) FROM payments WHERE NOT all_failed AND NOT any_pending AND NOT any_disputed), 'sales_cents', (SELECT coalesce(sum(net), 0) FROM payments WHERE NOT all_failed AND NOT any_pending AND NOT any_disputed) )$fn$;
REVOKE ALL ON FUNCTION public.analytics_visit_tally(uuid, uuid, text, bigint, bigint, bigint, bigint, bigint[], bigint[], boolean) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.analytics_all_time(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_visit_tally(uuid, uuid, text, bigint, bigint, bigint, bigint, bigint[], bigint[], boolean) TO service_role;
GRANT EXECUTE ON FUNCTION public.analytics_all_time(uuid, uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.analytics_report(p_creator_id uuid, p_property_type text, p_property_id uuid, p_default_website uuid, p_product_id uuid, p_cur_start bigint, p_cur_end bigint, p_prev_start bigint, p_prev_end bigint, p_cur_starts bigint[], p_prev_starts bigint[], p_part text DEFAULT 'all', p_now timestamptz DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path = public SET work_mem = '64MB' AS $fn$ DECLARE v_today date := (coalesce(p_now, now()) AT TIME ZONE 'UTC')::date; v_pred text := ''; v_pred_d text := ''; v_out jsonb := '{}'::jsonb; v_one jsonb; v_part jsonb; v_w text; v_ws timestamptz; v_we timestamptz; v_starts timestamptz[]; v_rolled date[]; v_from timestamptz[]; v_to timestamptz[]; v_run_from timestamptz; v_day date; v_d0 timestamptz; v_d1 timestamptz; BEGIN IF p_creator_id IS NULL OR p_cur_start IS NULL OR p_cur_end IS NULL OR p_cur_end <= p_cur_start THEN RAISE EXCEPTION 'analytics_report: a creator and a period are needed'; END IF; IF p_property_type IS NOT NULL AND p_property_type NOT IN ('creator_page', 'onepage', 'website') THEN RAISE EXCEPTION 'analytics_report: unknown property type %', p_property_type; END IF; IF coalesce(p_part, '') NOT IN ('all', 'figures', 'detail') THEN RAISE EXCEPTION 'analytics_report: unknown part %', p_part; END IF; /* Every read below is given the same arguments: $1 the creator, $2 the property type, $3 the property id, $4 the product, $5 and $6 the period, $7 its buckets, $8 the rolled up days, $9 and $10 the stretches read from the events, $11 the live website. The property and the product are conditions of their own, so each read is planned for what it is asked. A website row that never knew its install is the live website's. */ IF p_property_type IS NOT NULL THEN v_pred := ' AND e.property_type = $2'; IF p_property_type = 'website' AND p_property_id IS NOT NULL THEN v_pred := v_pred || CASE WHEN p_property_id = p_default_website THEN ' AND (e.property_id = $3 OR e.property_id IS NULL)' ELSE ' AND e.property_id = $3' END; END IF; END IF; v_pred_d := replace(v_pred, 'e.', 'd.'); IF p_product_id IS NOT NULL THEN v_pred := v_pred || ' AND e.product_id = $4'; END IF; FOREACH v_w IN ARRAY ARRAY['cur', 'prev'] LOOP v_ws := timestamptz 'epoch' + (CASE v_w WHEN 'cur' THEN p_cur_start ELSE coalesce(p_prev_start, p_cur_start) END) * interval '1 millisecond'; v_we := greatest(v_ws, timestamptz 'epoch' + (CASE v_w WHEN 'cur' THEN p_cur_end ELSE coalesce(p_prev_end, p_cur_start) END) * interval '1 millisecond'); v_starts := ARRAY(SELECT timestamptz 'epoch' + x * interval '1 millisecond' FROM unnest(coalesce(CASE v_w WHEN 'cur' THEN p_cur_starts ELSE p_prev_starts END, '{}'::bigint[])) WITH ORDINALITY u(x, i) ORDER BY i); v_one := '{}'::jsonb; IF p_part IN ('all', 'figures') THEN /* VISITORS: distinct in the period and in each bucket of the chart, counted from the page views themselves (visitors are never added up from days): one read, a count per bucket and visitor, and the period's visitors from those. */ EXECUTE format($q$ WITH bv AS (SELECT CASE WHEN cardinality($7::timestamptz[]) > 0 THEN width_bucket(e.created_at, $7::timestamptz[]) - 1 ELSE -1 END AS b, (coalesce(nullif(e.visitor_id, ''), nullif(e.session_id, ''), 'e:' || e.id::text) COLLATE "C") AS v, count(*) AS n, count(e.product_id) AS pn FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'view' AND e.created_at >= $5 AND e.created_at < $6 %1$s GROUP BY 1, 2), people AS (SELECT v, sum(pn) AS pn FROM bv GROUP BY v), per_b AS (SELECT b, count(*) AS visitors, sum(n) AS views FROM bv GROUP BY b) SELECT jsonb_build_object('visitors', (SELECT count(*) FROM people), 'product_visitors', (SELECT count(*) FROM people WHERE pn > 0), 'product_views', coalesce((SELECT sum(pn) FROM people), 0), 'views', coalesce((SELECT sum(views) FROM per_b), 0), 'visitor_buckets', coalesce((SELECT jsonb_agg(coalesce(p.visitors, 0) ORDER BY g.i) FROM generate_series(0, cardinality($7::timestamptz[]) - 1) g(i) LEFT JOIN per_b p ON p.b = g.i), '[]'::jsonb), 'view_buckets', coalesce((SELECT jsonb_agg(coalesce(p.views, 0) ORDER BY g.i) FROM generate_series(0, cardinality($7::timestamptz[]) - 1) g(i) LEFT JOIN per_b p ON p.b = g.i), '[]'::jsonb)) $q$, v_pred) INTO v_part USING p_creator_id, p_property_type, p_property_id, p_product_id, v_ws, v_we, v_starts, NULL::date[], NULL::timestamptz[], NULL::timestamptz[], p_default_website; v_one := v_one || v_part; /* LINK CLICKS in each bucket. A link is nobody's product: none when a product is chosen. */ EXECUTE format($q$ WITH c AS (SELECT CASE WHEN cardinality($7::timestamptz[]) > 0 THEN width_bucket(e.created_at, $7::timestamptz[]) - 1 ELSE -1 END AS b, count(*) AS n FROM public.analytics_events e WHERE $4::uuid IS NULL AND e.creator_id = $1 AND e.event_type = 'link_click' AND e.created_at >= $5 AND e.created_at < $6 %1$s GROUP BY 1) SELECT jsonb_build_object('clicks', coalesce((SELECT sum(n) FROM c), 0), 'click_buckets', coalesce((SELECT jsonb_agg(coalesce(c.n, 0) ORDER BY g.i) FROM generate_series(0, cardinality($7::timestamptz[]) - 1) g(i) LEFT JOIN c ON c.b = g.i), '[]'::jsonb)) $q$, replace(v_pred, ' AND e.product_id = $4', '')) INTO v_part USING p_creator_id, p_property_type, p_property_id, p_product_id, v_ws, v_we, v_starts, NULL::date[], NULL::timestamptz[], NULL::timestamptz[], p_default_website; v_one := v_one || v_part; END IF; IF p_part IN ('all', 'detail') AND v_w = 'cur' THEN /* PAGES and PRODUCTS: their page views, and how many visitors saw each. The period itself only: the lists are not compared. */ EXECUTE format($q$ WITH pv AS (SELECT e.property_type AS pt, e.property_id AS pid, e.path COLLATE "C" AS path, (coalesce(nullif(e.visitor_id, ''), nullif(e.session_id, ''), 'e:' || e.id::text) COLLATE "C") AS v, count(*) AS n, count(e.product_id) AS pn FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'view' AND e.created_at >= $5 AND e.created_at < $6 %1$s GROUP BY 1, 2, 3, 4), prv AS (SELECT e.product_id, (coalesce(nullif(e.visitor_id, ''), nullif(e.session_id, ''), 'e:' || e.id::text) COLLATE "C") AS v, count(*) AS n FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'view' AND e.product_id IS NOT NULL AND e.created_at >= $5 AND e.created_at < $6 %1$s GROUP BY 1, 2) SELECT jsonb_build_object('pages', coalesce((SELECT jsonb_agg(jsonb_build_array(t.pt, t.pid, t.path, t.views, t.visitors) ORDER BY t.views DESC, t.visitors DESC, t.path) FROM (SELECT pt, pid, path, sum(n) AS views, count(*) AS visitors FROM pv GROUP BY 1, 2, 3 ORDER BY 4 DESC, 5 DESC, 3 LIMIT 50) t), '[]'::jsonb), 'products', coalesce((SELECT jsonb_agg(jsonb_build_array(t.product_id, t.views, t.visitors) ORDER BY t.views DESC, t.product_id) FROM (SELECT product_id, sum(n) AS views, count(*) AS visitors FROM prv GROUP BY 1) t), '[]'::jsonb)) $q$, v_pred) INTO v_part USING p_creator_id, p_property_type, p_property_id, p_product_id, v_ws, v_we, v_starts, NULL::date[], NULL::timestamptz[], NULL::timestamptz[], p_default_website; v_one := v_one || v_part; /* STARTED CHECKOUTS, for the funnel: the visitors with a checkout_start. LINKS: clicks per link, and who clicked. */ EXECUTE format($q$ SELECT jsonb_build_object('checkouts', (SELECT count(DISTINCT (coalesce(nullif(e.visitor_id, ''), nullif(e.session_id, ''), 'e:' || e.id::text) COLLATE "C")) FROM public.analytics_events e WHERE e.creator_id = $1 AND e.event_type = 'checkout_start' AND e.created_at >= $5 AND e.created_at < $6 %1$s), 'links', coalesce((SELECT jsonb_agg(jsonb_build_array(t.pt, t.pid, t.link, t.clicks, t.visitors) ORDER BY t.clicks DESC, t.link) FROM (SELECT e.property_type AS pt, e.property_id AS pid, coalesce(e.link_id, e.link_url, '') COLLATE "C" AS link, count(*) AS clicks, count(DISTINCT (coalesce(nullif(e.visitor_id, ''), nullif(e.session_id, ''), 'e:' || e.id::text) COLLATE "C")) AS visitors FROM public.analytics_events e WHERE $4::uuid IS NULL AND e.creator_id = $1 AND e.event_type = 'link_click' AND e.created_at >= $5 AND e.created_at < $6 %2$s GROUP BY 1, 2, 3 ORDER BY 4 DESC, 3 LIMIT 50) t), '[]'::jsonb)) $q$, v_pred, replace(v_pred, ' AND e.product_id = $4', '')) INTO v_part USING p_creator_id, p_property_type, p_property_id, p_product_id, v_ws, v_we, v_starts, NULL::date[], NULL::timestamptz[], NULL::timestamptz[], p_default_website; v_one := v_one || v_part; END IF; IF p_part IN ('all', 'detail') THEN /* VISITS AND WHERE THEY CAME FROM. Every UTC day wholly inside the period that the daily rollup holds, and that is over, is read from analytics_property_daily; the rest (the part days at either edge, today, a day not rolled up yet) is counted from the events by analytics_property_counts, the very function the rollup is made with, so the two cannot disagree. A visit is counted in the quarter hour it began (session_slots), which lies wholly inside one bucket of any time zone's chart. With a product chosen, all of it from the events. */ v_rolled := '{}'; v_from := '{}'; v_to := '{}'; v_run_from := NULL; IF v_we > v_ws THEN FOR v_day IN SELECT g::date FROM generate_series((v_ws AT TIME ZONE 'UTC')::date, ((v_we - interval '1 microsecond') AT TIME ZONE 'UTC')::date, interval '1 day') g LOOP v_d0 := v_day::timestamp AT TIME ZONE 'UTC'; v_d1 := (v_day + 1)::timestamp AT TIME ZONE 'UTC'; IF p_product_id IS NULL AND v_d0 >= v_ws AND v_d1 <= v_we AND v_day < v_today AND EXISTS (SELECT 1 FROM public.analytics_rollup_days r WHERE r.day = v_day) THEN v_rolled := v_rolled || v_day; IF v_run_from IS NOT NULL THEN v_from := v_from || v_run_from; v_to := v_to || v_d0; v_run_from := NULL; END IF; ELSIF v_run_from IS NULL THEN v_run_from := greatest(v_d0, v_ws); END IF; END LOOP; IF v_run_from IS NOT NULL THEN v_from := v_from || v_run_from; v_to := v_to || v_we; END IF; END IF; EXECUTE format($q$ WITH parts AS (SELECT d.day, d.sessions, d.sources, d.referrers, d.campaigns, d.devices, d.countries, d.browsers, d.session_slots FROM public.analytics_property_daily d WHERE d.creator_id = $1 AND d.day = ANY ($8) %1$s UNION ALL SELECT c.day, c.sessions, c.sources, c.referrers, c.campaigns, c.devices, c.countries, c.browsers, c.session_slots FROM unnest($9::timestamptz[], $10::timestamptz[]) AS r(f, t), LATERAL public.analytics_property_counts(r.f, r.t, $1, $2, $3, $11, $4) c), pairs AS (SELECT 'source' AS kind, x.k, x.v::bigint AS n FROM parts p, jsonb_each_text(p.sources) x(k, v) UNION ALL SELECT 'referrer', x.k, x.v::bigint FROM parts p, jsonb_each_text(p.referrers) x(k, v) UNION ALL SELECT 'campaign', x.k, x.v::bigint FROM parts p, jsonb_each_text(p.campaigns) x(k, v) UNION ALL SELECT 'device', x.k, x.v::bigint FROM parts p, jsonb_each_text(p.devices) x(k, v) UNION ALL SELECT 'country', x.k, x.v::bigint FROM parts p, jsonb_each_text(p.countries) x(k, v) UNION ALL SELECT 'browser', x.k, x.v::bigint FROM parts p, jsonb_each_text(p.browsers) x(k, v)), slots AS (SELECT CASE WHEN cardinality($7::timestamptz[]) > 0 THEN width_bucket((p.day::timestamp AT TIME ZONE 'UTC') + x.k::int * interval '15 minutes', $7::timestamptz[]) - 1 ELSE -1 END AS b, sum(x.v::bigint) AS n FROM parts p, jsonb_each_text(p.session_slots) x(k, v) GROUP BY 1) SELECT jsonb_build_object('sessions', coalesce((SELECT sum(sessions) FROM parts), 0), 'session_buckets', coalesce((SELECT jsonb_agg(coalesce(s.n, 0) ORDER BY g.i) FROM generate_series(0, cardinality($7::timestamptz[]) - 1) g(i) LEFT JOIN slots s ON s.b = g.i), '[]'::jsonb), 'rolled_days', cardinality($8::date[]), 'raw_runs', cardinality($9::timestamptz[]), 'maps', coalesce((SELECT jsonb_object_agg(kind, m) FROM (SELECT kind, jsonb_object_agg(k, n) AS m FROM (SELECT kind, k, sum(n) AS n FROM pairs GROUP BY 1, 2) s GROUP BY 1) y), '{}'::jsonb)) $q$, v_pred_d) INTO v_part USING p_creator_id, p_property_type, p_property_id, p_product_id, v_ws, v_we, v_starts, v_rolled, v_from, v_to, p_default_website; v_one := v_one || v_part; END IF; v_out := v_out || jsonb_build_object(v_w, v_one); END LOOP; RETURN v_out; END; $fn$;
REVOKE ALL ON FUNCTION public.analytics_report(uuid, text, uuid, uuid, uuid, bigint, bigint, bigint, bigint, bigint[], bigint[], text, timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_report(uuid, text, uuid, uuid, uuid, bigint, bigint, bigint, bigint, bigint[], bigint[], text, timestamptz) TO service_role;
